import * as THREE from 'three';

const canvas = document.querySelector('#view');
const renderer = new THREE.WebGLRenderer({canvas, antialias: true, powerPreference: 'low-power'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = false;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x121917);
scene.fog = new THREE.FogExp2(0x121917, 0.0075);
const camera = new THREE.PerspectiveCamera(43, window.innerWidth / window.innerHeight, 0.2, 400);
const hemi = new THREE.HemisphereLight(0xc9d8ce, 0x333b35, 1.8); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xe4ebe2, 2.5); moon.position.set(-35, 70, 30); scene.add(moon);
const fill = new THREE.PointLight(0x8db1a0, 100, 160); fill.position.set(0, 25, 0); scene.add(fill);
const groundMat = new THREE.MeshStandardMaterial({color:0x626963, roughness:1, metalness:0});
const roadMat = new THREE.MeshStandardMaterial({color:0x343a36, roughness:1});
const ground = new THREE.Mesh(new THREE.PlaneGeometry(220,220,1,1),groundMat); ground.rotation.x=-Math.PI/2; ground.position.y=-0.7; scene.add(ground);
const world = new THREE.Group(); scene.add(world);
const material=(color,emissive=0x000000,intensity=0)=>new THREE.MeshStandardMaterial({color,roughness:.92,emissive,emissiveIntensity:intensity});
const matRock=material(0x777e78), matBuild=material(0x666d66), matEdge=material(0x343b36), matRoad=material(0x3e4540), matWarm=material(0xc8d1c9,0x69736b,.42);
const matAlly=material(0x75d08a,0x41b65e,1.35), matEnemy=material(0xe4e8df,0xb7c4b8,1.7), matEnemyDark=material(0x9ca49d,0x636e65,.8), matTurret=material(0xb9c2ba,0x79867b,.8);
const boxGeo=new THREE.BoxGeometry(1,1,1), wheelGeo=new THREE.CylinderGeometry(.18,.18,.12,8), sphereGeo=new THREE.SphereGeometry(1,8,6);
const rand=(a,b)=>a+Math.random()*(b-a);
function addBox(parent,mat,pos,scale){const m=new THREE.Mesh(boxGeo,mat);m.position.set(...pos);m.scale.set(...scale);parent.add(m);return m;}
function addRock(x,z,sx,sy,sz){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(1,0),matRock);m.position.set(x,sy*.5-.5,z);m.scale.set(sx,sy,sz);m.rotation.set(rand(-.18,.18),rand(0,3),rand(-.18,.18));world.add(m);}
// Roads, outpost and a sparse low-poly desert settlement.
function makeRoad(points,width=4){const curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,-.57,z)));const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,100,width*.5,5,false),matRoad);world.add(mesh);return curve;}
const route=makeRoad([[-3,54],[0,38],[1,19],[-2,2],[0,-19],[3,-42],[0,-58]],5.1);
makeRoad([[0,7],[20,12],[39,18],[60,17]],3.2); makeRoad([[-1,-23],[-22,-20],[-43,-22],[-62,-18]],3.3);
// Broken lane markings and roadside structures.
for(let i=0;i<11;i++){const p=route.getPointAt(i/11);addBox(world,material(0xb2b7ae),[p.x,-.52,p.z],[.12,.025,1.25]);}
for(let i=0;i<58;i++){
 const x=rand(-88,88),z=rand(-83,82); if(Math.abs(x)<13&&Math.abs(z)<60)continue;
 if(Math.random()<.68)addRock(x,z,rand(1.2,5),rand(1,7),rand(1,4));
 else {const w=rand(4,9),h=rand(2,5),d=rand(4,8);addBox(world,matBuild,[x,h/2-.55,z],[w,h,d]);addBox(world,matEdge,[x,h-.4,z],[w+.2,.22,d+.2]);if(Math.random()<.55)addBox(world,matWarm,[x,rand(.3,h-.5),z+d*.51],[.65,.45,.05]);}
}
// A military compound, storage tanks, watchtowers and perimeter lights.
for(const [x,z,w,d,h] of [[-30,-2,12,10,5],[33,8,15,12,4],[25,-41,10,8,3],[-37,36,9,7,3]]){
 addBox(world,matBuild,[x,h/2-.45,z],[w,h,d]);addBox(world,matEdge,[x,h-.32,z],[w+.5,.25,d+.5]);
 for(let k=0;k<3;k++) addBox(world,matWarm,[x+(k-1)*2.6,.6,z+d*.505],[1,.65,.06]);
}
for(const [x,z] of [[-24,4],[29,15],[41,2],[-39,33]]){const pole=addBox(world,matEdge,[x,4,z],[.2,8,.2]);const lamp=new THREE.PointLight(0xcbd6cb,13,16);lamp.position.set(x,7,z);world.add(lamp);}
// Mountain ridges on the edge of the playable basin.
for(let i=0;i<23;i++){const angle=i/23*Math.PI*2,r=96+rand(-4,6),h=rand(12,27);const m=new THREE.Mesh(new THREE.ConeGeometry(rand(9,17),h,5),matRock);m.position.set(Math.cos(angle)*r,h/2-1,Math.sin(angle)*r);m.rotation.y=rand(0,3);world.add(m);}
// World labels rendered as simple luminous marker beacons.
const markerMat=material(0x9ce5a9,0x73dd88,2.4);
function makeMarker(colorMat){const g=new THREE.Group();const stem=new THREE.Mesh(new THREE.CylinderGeometry(.07,.07,2.5,6),colorMat);stem.position.y=1.1;g.add(stem);const cap=new THREE.Mesh(new THREE.SphereGeometry(.32,8,6),colorMat);cap.position.y=2.45;g.add(cap);world.add(g);return g;}
const extraction=makeMarker(markerMat);extraction.position.set(0,0,-52);
const reticleWorld=new THREE.Vector3();
const tracerMat=material(0xffdf9a,0xffa43c,4);const explosionMat=material(0xffd0a1,0xff6a28,3);
let orbitAngle=0, aimX=0,aimZ=0,aimTargetX=0,aimTargetZ=0, zoom=1, thermal='WHITE HOT';
let started=false,paused=false,gameOver=false,startTime=0,lastTime=0,elapsed=0,kills=0,friendlyLosses=0,shots=0,penalty=0;
const allies=[],enemies=[],projectiles=[],effects=[];let nextWave=0,wave=0,selectedWeapon=2,ammo=[160,55,24],reloadUntil=0,fireHeld=false,fireTimer=0,shotKick=0;
const weaponData=[{name:'M61 · 25 MM',delay:.105,reload:0,velocity:118,radius:1.6,damage:18,ammo:160},{name:'L60 · 40 MM',delay:.78,reload:.45,velocity:83,radius:5.4,damage:57,ammo:55},{name:'M102 · 105 MM',delay:2.1,reload:1.05,velocity:60,radius:11,damage:125,ammo:24}];
function makeVehicle(type,index){
 const g=new THREE.Group();const friendly=type==='ally';const base=friendly?matAlly:matEnemy;const dark=friendly?matAlly:matEnemyDark;
 addBox(g,base,[0,.72,0],[friendly?2.45:2.8,.85,friendly?4.8:5.4]); addBox(g,dark,[0,1.28,-.2],[1.55,.47,2.2]);
 addBox(g,matEdge,[0,1.44,.05],[.16,.5,1.8]);
 for(const side of [-1,1]) for(const z of [-1.6,-.55,.65,1.55]){const wheel=new THREE.Mesh(wheelGeo,matEdge);wheel.rotation.z=Math.PI/2;wheel.position.set(side*(friendly?1.19:1.38),.53,z);g.add(wheel);}
 const turret=addBox(g,friendly?matAlly:matTurret,[0,1.65,-.25],[friendly?1.05:1.2,.4,1.25]);addBox(g,base,[0,1.84,-1],[.14,.16,1.5]);
 if(!friendly){const glow=new THREE.PointLight(0xdce9dc,10,13);glow.position.set(0,1.5,0);g.add(glow);}
 world.add(g);return {group:g,type,friendly,index,hp:friendly?100:100,alive:true,speed:friendly?.17:rand(.075,.12),routeT:friendly?index*.045:rand(.25,.68),targetIndex:0,attackCooldown:rand(1.5,3),damageFlash:0};
}
for(let i=0;i<3;i++){const v=makeVehicle('ally',i);allies.push(v);}
function spawnEnemy(kind='armor'){
 const e=makeVehicle('enemy',wave*10+enemies.length);e.kind=kind;e.hp=kind==='truck'?64:100;e.speed=kind==='truck'?.095:.12;
 const side=Math.random()<.5?-1:1;e.routeT=rand(.15,.83);const p=route.getPointAt(e.routeT);e.group.position.set(p.x+side*rand(8,15),0,p.z+rand(-7,7));e.destination=allies[Math.floor(Math.random()*allies.length)];enemies.push(e);return e;
}
function setVehicleHud(){allies.forEach((v,i)=>{const hp=Math.max(0,v.hp);document.querySelector(`#ally${i+1}-health`).style.width=hp+'%';document.querySelector(`#ally${i+1}-status`).textContent=v.alive?`${Math.ceil(hp)}%`:'LOST';document.querySelector(`#ally${i+1}-status`).style.color=v.alive?'':'#de8f7a';});document.querySelector('#hostile-count').textContent=String(enemies.filter(e=>e.alive).length+Math.max(0,5-wave)).padStart(2,'0');}
function routePoint(t){return route.getPointAt(THREE.MathUtils.clamp(t,0,.999));}
function alignToPath(vehicle,t){const p=routePoint(t),q=routePoint(Math.min(.999,t+.006));vehicle.group.position.x=p.x;vehicle.group.position.z=p.z;vehicle.group.rotation.y=Math.atan2(q.x-p.x,-(q.z-p.z));}
allies.forEach((a,i)=>alignToPath(a,.84-i*.075));

