// Compact particle bursts and ballistic tracers keep the scene readable on phones.
function burst(position,scale=1,allyHit=false){
 const group=new THREE.Group();group.position.copy(position);world.add(group);
 const core=new THREE.Mesh(new THREE.SphereGeometry(.55,8,6),allyHit?material(0xff9a73,0xff3925,4):explosionMat);core.scale.setScalar(.3);group.add(core);
 const light=new THREE.PointLight(allyHit?0xff643f:0xffa45a,allyHit?15:24,scale*13);group.add(light);
 for(let i=0;i<7;i++){const particle=new THREE.Mesh(sphereGeo,i%2?matWarm:explosionMat);particle.scale.setScalar(rand(.12,.38)*scale);particle.position.set(rand(-.5,.5),rand(-.2,.7),rand(-.5,.5));particle.userData.v=new THREE.Vector3(rand(-1,1),rand(.2,1.8),rand(-1,1)).multiplyScalar(rand(2,7)*scale);group.add(particle);}
 effects.push({group,core,light,life:0,duration:.65+scale*.12,scale});
}
function makeShot(target,kind){const geo=new THREE.SphereGeometry(kind===0?.12:kind===1?.23:.36,6,5);const mesh=new THREE.Mesh(geo,tracerMat);mesh.position.copy(camera.position);world.add(mesh);const from=mesh.position.clone();const dest=target.clone();const dist=from.distanceTo(dest);const velocity=weaponData[kind].velocity;projectiles.push({mesh,from,to:dest,life:0,duration:dist/velocity,kind,target:target.clone()});}
const audio={ctx:null,master:null,muted:false};
function initAudio(){if(audio.ctx)return;try{audio.ctx=new(window.AudioContext||window.webkitAudioContext)();audio.master=audio.ctx.createGain();audio.master.gain.value=.24;audio.master.connect(audio.ctx.destination);const osc=audio.ctx.createOscillator(),gain=audio.ctx.createGain();osc.type='sawtooth';osc.frequency.value=44;gain.gain.value=.025;osc.connect(gain);gain.connect(audio.master);osc.start();}catch(e){}}
function tone(freq,duration,volume=.1,type='sawtooth',endFreq=freq*.5){if(!audio.ctx||audio.muted)return;const t=audio.ctx.currentTime,o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,endFreq),t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(audio.master);o.start(t);o.stop(t+duration);}
function fireSound(kind){if(!audio.ctx||audio.muted)return;if(kind===0){tone(110,.08,.08,'sawtooth',48);tone(61,.1,.045,'triangle',35);}else if(kind===1){tone(92,.26,.13,'sawtooth',35);tone(380,.08,.045,'square',90);}else{tone(56,.48,.2,'sawtooth',23);tone(330,.22,.07,'triangle',42);}}
function radioSound(){tone(680,.04,.035,'square',530);setTimeout(()=>tone(510,.07,.025,'square',390),60);}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1900);}
function radioMessage(text){document.querySelector('#radio-line').textContent=`“${text}”`;radioSound();}
const radioLines=['Hostile trucks, bearing north of the route. Weapons free on confirmed targets.','Alpha convoy, we have eyes on you. Keep moving to the extraction point.','Good effects on target. No friendlies in the impact area.','Gunship, two vehicles are pushing through the east approach.','Alpha Actual, taking fire! Suppress those hostiles!','Convoy is making good time. Stay with us, gunship.','Solid hit! Target no longer moving.','Watch your fire near the convoy. They are marked green.'];
function getGroundPoint(nx=0,ny=0){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(nx,ny),camera);const hit=new THREE.Vector3();const plane=new THREE.Plane(new THREE.Vector3(0,1,0),.55);if(ray.ray.intersectPlane(plane,hit))return hit;return new THREE.Vector3(aimX,0,aimZ);}
function findTarget(){const point=getGroundPoint(0,0);let nearest=null,dist=Infinity;for(const e of enemies){if(!e.alive)continue;const d=e.group.position.distanceTo(point);if(d<dist){dist=d;nearest=e;}}return {point,enemy:nearest,distance:dist};}
function updateTargetHud(){const t=findTarget(),name=document.querySelector('#target-name'),state=document.querySelector('#target-state');if(t.enemy&&t.distance<22){name.textContent=t.enemy.kind==='truck'?'HOSTILE TECHNICAL':'HOSTILE APC';state.textContent='TRACKING';state.style.color='#f1c47f';document.querySelector('#target-range').textContent=`${Math.round(camera.position.distanceTo(t.enemy.group.position)*12)} M`;document.querySelector('#target-type').textContent=t.enemy.kind==='truck'?'LIGHT':'ARMOR';document.querySelector('#cross-range').textContent=`${Math.round(camera.position.distanceTo(t.enemy.group.position)*12)} M`;}else{name.textContent='NO HOSTILE LOCK';state.textContent='SCANNING';state.style.color='';document.querySelector('#target-range').textContent='—';document.querySelector('#target-type').textContent='—';document.querySelector('#cross-range').textContent='— M';}}
function shoot(){if(!started||paused||gameOver)return;const now=performance.now()/1000;if(now<reloadUntil)return;if(ammo[selectedWeapon]<=0){toast('WEAPON DRY · SELECT ANOTHER SYSTEM');tone(160,.11,.08,'square',120);return;}
 const data=weaponData[selectedWeapon],aim=findTarget();let point=aim.point.clone();if(aim.enemy&&aim.distance<26)point.copy(aim.enemy.group.position).add(new THREE.Vector3(0,.8,0));
 // Friendly PID interlock warns but never prevents player action: the penalty is immediate.
 let friendly=null,friendDist=Infinity;for(const a of allies)if(a.alive){const d=a.group.position.distanceTo(point);if(d<friendDist){friendDist=d;friendly=a;}}
 const isFriendly=friendly&&friendDist<data.radius+2&&(!aim.enemy||friendDist<aim.distance);
 makeShot(point,selectedWeapon);shots++;ammo[selectedWeapon]--;fireSound(selectedWeapon);shotKick=selectedWeapon===2?8:selectedWeapon===1?3:1;
 reloadUntil=now+data.delay+(selectedWeapon===1?data.reload:selectedWeapon===2?data.reload:0);fireTimer=now+data.delay;
 if(isFriendly){friendly.hp=Math.max(0,friendly.hp-(selectedWeapon===2?52:selectedWeapon===1?28:12));if(friendly.hp<=0){friendly.alive=false;friendlyLosses++;radioMessage('Alpha unit lost. Gunship, watch your fire!');}else radioMessage('Cease fire! Friendly unit hit. Watch your target identification.');penalty++;burst(friendly.group.position.clone().add(new THREE.Vector3(0,1,0)),.8,true);toast('FRIENDLY FIRE · ROE VIOLATION');document.querySelector('.crosshair').classList.add('friendly-hit');setTimeout(()=>document.querySelector('.crosshair').classList.remove('friendly-hit'),500);}
 setVehicleHud();updateWeaponHud();
}
function updateWeaponHud(){document.querySelectorAll('.weapon').forEach((el,i)=>el.classList.toggle('active',i===selectedWeapon));document.querySelector('#weapon-label').textContent=weaponData[selectedWeapon].name;document.querySelector('#ammo-count').textContent=ammo[selectedWeapon];}
function selectWeapon(i){selectedWeapon=i;updateWeaponHud();tone(390+i*90,.07,.045,'square',250);}
function damageEnemies(point,kind){const d=weaponData[kind];let hit=0;for(const e of enemies){if(!e.alive)continue;const dist=e.group.position.distanceTo(point);if(dist<d.radius+1){const amount=Math.max(18,d.damage*(1-dist/(d.radius+2)));e.hp-=amount;e.damageFlash=.4;hit++;if(e.hp<=0){e.alive=false;e.group.visible=false;kills++;burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),kind===2?1.4:kind===1?.8:.45);if(kills%2===0)radioMessage(radioLines[Math.floor(Math.random()*radioLines.length)]);}}}
 for(const a of allies){if(!a.alive)continue;const dist=a.group.position.distanceTo(point);if(dist<d.radius+1){a.hp=Math.max(0,a.hp-(d.damage*.8));if(a.hp<=0){a.alive=false;friendlyLosses++;a.group.visible=false;radioMessage('Alpha unit lost. We are down a vehicle!');}}}
 if(!hit)burst(point.clone(),kind===2?1.1:kind===1?.75:.4);setVehicleHud();}
function finish(win){if(gameOver)return;gameOver=true;fireHeld=false;document.querySelector('#fire-button').classList.remove('firing');document.querySelector('#mission-state').textContent=win?'MISSION COMPLETE':'MISSION FAILED';document.querySelector('#result-kicker').textContent=win?'MISSION DEBRIEF · SUCCESS':'MISSION DEBRIEF · CASUALTIES';document.querySelector('#result-icon').textContent=win?'✓':'×';document.querySelector('#result-icon').style.color=win?'#b6edbc':'#ef9b7c';document.querySelector('#result-title').textContent=win?'MISSION COMPLETE':'MISSION FAILED';document.querySelector('#result-copy').textContent=win?'Alpha convoy reached the extraction point. Excellent work, gunship.':'All friendly vehicles have been destroyed. The convoy did not make it.';document.querySelector('#score-kills').textContent=String(kills).padStart(2,'0');document.querySelector('#score-losses').textContent=String(friendlyLosses).padStart(2,'0');document.querySelector('#score-time').textContent=formatTime(elapsed);document.querySelector('#result-modal').classList.remove('hidden');radioMessage(win?'Alpha Actual, we are at the extraction point. Outstanding support.':'Gunship, all callsigns are down. Abort mission.');}
function formatTime(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}

