function fireSound(kind){if(!audio.ctx||audio.muted)return;if(kind===0){tone(110,.08,.08,'sawtooth',48);tone(61,.1,.045,'triangle',35);}else if(kind===1){tone(92,.26,.13,'sawtooth',35);tone(380,.08,.045,'square',90);}else{tone(56,.48,.2,'sawtooth',23);tone(330,.22,.07,'triangle',42);}}
